import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_HMAC_KEY = os.environ.get('HMAC_SECRET', 'default-key-for-dev')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        password_hash TEXT NOT NULL,
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_session(token):
    """Verify session token using HMAC - prevents token forgery"""
    if not token or ':' not in token:
        return None
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected = hmac.new(SECRET_HMAC_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return payload
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    session_user = verify_session(auth[7:])
    if not session_user:
        return jsonify({'error': 'invalid session'}), 401

    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Whitelist allowed search fields
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    if not value or len(value) > 100:
        return jsonify({'error': 'invalid query'}), 400

    db = get_db()
    # Build query with field from whitelist - field is safe
    # Value is user-controlled and inserted via string formatting
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, target_user, performed_by) VALUES (?, ?, ?)",
            ('search', f"{field}:{value[:20]}", session_user)
        )
        db.commit()
        return jsonify({'users': users})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    user = db.execute(
        "SELECT id, username, email, role FROM users WHERE id = ?", (user_id,)
    ).fetchone()

    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
